@Test
public void test() throws Exception {
    CombinerStage<Integer, Integer> stage = new CombinerStage<Integer, Integer>(new Combiner<Integer, Integer>() {

        @Override
        public Integer combine(Integer key, Integer old, Integer cur) {
            if (old != null) {
                return old.intValue() + cur.intValue();
            } else {
                return cur;
            }
        }
    }, new Observer<Entry<Integer, Integer>>() {

        private AtomicInteger x = new AtomicInteger(0);

        @Override
        public void onNext(Entry<Integer, Integer> value) {
            System.out.println(value.getKey() + "=" + value.getValue());
            x.incrementAndGet();
            try {
                if (!done)
                    Thread.sleep(10);
            } catch (InterruptedException e) {
                throw new IllegalStateException(e);
            }
        }

        @Override
        public void onError(Exception error) {
            System.err.println("onError called!");
            error.printStackTrace();
        }

        @Override
        public void onCompleted() {
            System.out.println("onCompleted " + x);
        }
    });
    o = stage.wireIn();
    WorkerThread[] workers = new WorkerThread[threadCount];
    for (int i = 0; i < threadCount; i++) {
        workers[i] = new WorkerThread();
    }
    long start = System.currentTimeMillis();
    for (int i = 0; i < threadCount; i++) {
        workers[i].start();
    }
    for (int i = 0; i < threadCount; i++) {
        workers[i].join();
    }
    o.onCompleted();
    long inStop = System.currentTimeMillis();
    done = true;
    stage.close();
    long outStop = System.currentTimeMillis();
    long eventCount = threadCount * eventsPerThread;
    double inelapsed = ((double) (inStop - start)) / 1000.0;
    double inoutelapsed = ((double) (outStop - start)) / 1000.0;
    System.out.println("Emitted " + eventCount + " events in " + inelapsed + " seconds (" + ((double) eventCount) / (inelapsed * 1000.0 * 1000.0) + " million events/sec)");
    System.out.println("Emitted/output " + eventCount + " events in " + inoutelapsed + " seconds (" + ((double) eventCount) / (inoutelapsed * 1000.0 * 1000.0) + " million events/sec)");
}

